prefix_map = {
    "buddhism": "rel",
    "food": "f",
    "animals": "a",
    "body": "b",
    "daily": "d",
    "travel": "t",
    "emotions": "e",
    "jobs": "j",
    "education": "edu",
    "tricky": "s"
}

ordered_cat_ids = [c["id"] for c in categories if c["id"] != "all"]
final_words = []

for cat_id in ordered_cat_ids:
    cat_list = list(by_cat.get(cat_id, []))
    existing_set = set(w["word"] for w in cat_list)
    start_idx = len(cat_list) + 1
    prefix = prefix_map[cat_id]

    for item in extra_words[cat_id]:
        if len(cat_list) >= 100:
            break
        w_text, pron, pos, meaning, ex, rom, eng = item
        # Ensure we add all 100 items
        cat_list.append({
            "id": f"{prefix}_{start_idx}",
            "word": w_text,
            "pronunciation": pron,
            "category": cat_id,
            "partOfSpeech": pos,
            "meaning": meaning,
            "exampleSentence": ex,
            "romanization": rom,
            "english": eng
        })
        start_idx += 1

    print(f"Category {cat_id}: {len(cat_list)} words")
    assert len(cat_list) == 100, f"Expected 100 words for {cat_id}, got {len(cat_list)}"
    final_words.extend(cat_list)

print(f"Total final words: {len(final_words)}")
assert len(final_words) == 1000, f"Expected 1000 words total, got {len(final_words)}"

